import 'package:dio/dio.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../../core/network/api_error.dart';
import '../../../core/network/dio_provider.dart';
import 'order_models.dart';

class OrdersRepository {
  OrdersRepository(this._dio);

  final Dio _dio;

  /// Submits a new order. [id] is generated by the app: sending the same id again returns
  /// the stored order instead of creating a second one, so retrying is always safe.
  Future<Order> submit({
    required String id,
    required int tableId,
    required List<NewLine> lines,
    String? note,
  }) {
    return _call(
      () => _dio.post<Map<String, dynamic>>(
        '/orders',
        data: {
          'id': id,
          'tableId': tableId,
          if (note != null && note.trim().isNotEmpty) 'note': note.trim(),
          'items': [for (final line in lines) line.toJson()],
        },
      ),
    );
  }

  /// Follow-up submission; [submissionNo] is the number this submission is expected to get.
  Future<Order> addItems({
    required String orderId,
    required int submissionNo,
    required List<NewLine> lines,
  }) {
    return _call(
      () => _dio.post<Map<String, dynamic>>(
        '/orders/$orderId/items',
        data: {
          'submissionNo': submissionNo,
          'items': [for (final line in lines) line.toJson()],
        },
      ),
    );
  }

  Future<Order> cancelItems(String orderId, List<int> itemIds) {
    return _call(
      () => _dio.post<Map<String, dynamic>>(
        '/orders/$orderId/cancellations',
        data: {'itemIds': itemIds},
      ),
    );
  }

  Future<Order> complete(String orderId) {
    return _call(
      () => _dio.post<Map<String, dynamic>>('/orders/$orderId/completion'),
    );
  }

  Future<List<Order>> openOrdersOfTable(int tableId) async {
    try {
      final response = await _dio.get<List<dynamic>>('/tables/$tableId/orders');
      return [
        for (final item in response.data ?? <dynamic>[])
          Order.fromJson(item as Map<String, dynamic>),
      ];
    } on DioException catch (e) {
      throw ApiError.from(e);
    }
  }

  Future<Order> _call(
    Future<Response<Map<String, dynamic>>> Function() request,
  ) async {
    try {
      final response = await request();
      return Order.fromJson(response.data!);
    } on DioException catch (e) {
      throw ApiError.from(e);
    }
  }
}

final ordersRepositoryProvider = Provider<OrdersRepository>((ref) {
  return OrdersRepository(ref.watch(dioProvider));
});
